import sys
sys.path.insert(0, 'src')
from json_patch import apply_patch, PatchError

doc = {'a/b': {'~key': [1, {'x': 2}]}, 'arr': ['a', 'b']}
out = apply_patch(doc, [
    {'op': 'copy', 'from': '/a~1b/~0key/1', 'path': '/arr/1'},
    {'op': 'move', 'from': '/a~1b/~0key/0', 'path': '/arr/-'},
    {'op': 'replace', 'path': '/a~1b/~0key/0/x', 'value': 3},
])
assert out == {'a/b': {'~key': [{'x': 3}]}, 'arr': ['a', {'x': 2}, 'b', 1]}
assert doc == {'a/b': {'~key': [1, {'x': 2}]}, 'arr': ['a', 'b']}
for ops in ([{'op': 'remove', 'path': '/missing'}], [{'op': 'add', 'path': '/arr/01', 'value': 1}], [{'op': 'copy', 'from': '/arr/0', 'path': '/bad~2'}]):
    try:
        apply_patch(doc, ops)
    except PatchError:
        pass
    else:
        raise AssertionError('expected PatchError')
print('manual JSON Patch checks passed')
